class ZodError extends Error{constructor(issues){super(issues.map(i=>`${i.path?.join('.')||'<root>'}: ${i.message}`).join('; '));this.name='ZodError';this.issues=issues}}
const ok=data=>({success:true,data}); const fail=(path,msg)=>({success:false,error:new ZodError([{path,message:msg}])});
class S{constructor(fn){this.fn=fn;this._optional=false;this._nullable=false;this._default=undefined} _parse(v,p=[]){if(v===undefined){if(this._default!==undefined)return ok(typeof this._default==='function'?this._default():this._default); if(this._optional)return ok(v)} if(v===null&&this._nullable)return ok(v); return this.fn(v,p)} safeParse(v){return this._parse(v,[])} parse(v){const r=this.safeParse(v); if(!r.success)throw r.error; return r.data} optional(){const n=this._clone();n._optional=true;return n} nullable(){const n=this._clone();n._nullable=true;return n} default(v){const n=this._clone();n._default=v;return n} _clone(){const n=new S(this.fn);Object.assign(n,this);return n}}
class Obj extends S{constructor(shape){super((v,p)=>{if(!v||typeof v!=='object'||Array.isArray(v))return fail(p,'Expected object'); const out={...v}; for(const [k,s] of Object.entries(shape)){const r=s._parse(v[k],[...p,k]); if(!r.success)return r; if(r.data!==undefined)out[k]=r.data} return ok(out)});this.shape=shape} extend(extra){return new Obj({...this.shape,...extra})} passthrough(){return this} _clone(){const n=new Obj(this.shape);Object.assign(n,this);return n}}
class Arr extends S{constructor(item){super((v,p)=>{if(!Array.isArray(v))return fail(p,'Expected array'); const out=[]; for(let i=0;i<v.length;i++){const r=item._parse(v[i],[...p,i]); if(!r.success)return r; out.push(r.data)} return ok(out)});this.item=item} min(n){const base=this; const s=new Arr(this.item); Object.assign(s,this); s.fn=(v,p)=>{const r=base.fn(v,p); if(!r.success)return r; return r.data.length<n?fail(p,`Array must contain at least ${n} element(s)`):r}; return s} _clone(){const n=new Arr(this.item);Object.assign(n,this);return n}}
const string=()=>new S((v,p)=>typeof v==='string'?ok(v):fail(p,'Expected string'));
const boolean=()=>new S((v,p)=>typeof v==='boolean'?ok(v):fail(p,'Expected boolean'));
const addNumMethods=s=>{s.int=()=>addNumMethods(new S((v,p)=>{const r=s._parse(v,p); if(!r.success)return r; return Number.isInteger(r.data)?ok(r.data):fail(p,'Expected integer')}));s.positive=()=>addNumMethods(new S((v,p)=>{const r=s._parse(v,p); if(!r.success)return r; return typeof r.data==='number'&&r.data>0?ok(r.data):fail(p,'Expected positive number')}));s.nonnegative=()=>addNumMethods(new S((v,p)=>{const r=s._parse(v,p); if(!r.success)return r; return typeof r.data==='number'&&r.data>=0?ok(r.data):fail(p,'Expected nonnegative number')}));return s};
const number=()=>addNumMethods(new S((v,p)=>typeof v==='number'&&!Number.isNaN(v)?ok(v):fail(p,'Expected number')));
const z={ZodError,object:(x)=>new Obj(x),array:(x)=>new Arr(x),string,boolean,number:()=>addNumMethods(number()),literal:(x)=>new S((v,p)=>v===x?ok(v):fail(p,`Expected literal ${x}`)),null:()=>new S((v,p)=>v===null?ok(v):fail(p,'Expected null')),enum:(xs)=>new S((v,p)=>xs.includes(v)?ok(v):fail(p,'Invalid enum value')),unknown:()=>new S((v)=>ok(v)),record:(val)=>new S((v,p)=>v&&typeof v==='object'&&!Array.isArray(v)?ok(v):fail(p,'Expected record')),union:(schemas)=>new S((v,p)=>{for(const s of schemas){const r=s._parse(v,p);if(r.success)return r}return fail(p,'Invalid union')}),coerce:{number:()=>addNumMethods(new S((v,p)=>{const n=Number(v);return Number.isNaN(n)?fail(p,'Expected number'):ok(n)}))}};
